// New articles, 14 November 2026 (part 1): thirteen world cities, four natural wonders and three famous landmarks.
addEventListener("DOMContentLoaded",()=>{Object.assign(window.LOC=window.LOC||{},{shanghai:[121.47,31.23,"China",36,"Shanghai"],losangeles:[-118.24,34.05,"United States of America",36,"Los Angeles"],chicago:[-87.63,41.88,"United States of America",36,"Chicago"],amsterdam:[4.90,52.37,"Netherlands",36,"Amsterdam"],barcelona:[2.17,41.39,"Spain",36,"Barcelona"],vienna:[16.37,48.21,"Austria",36,"Vienna"],prague:[14.42,50.08,"Czechia",36,"Prague"],stpetersburg:[30.31,59.94,"Russia",36,"St Petersburg"],delhi:[77.21,28.61,"India",36,"Delhi"],capetown:[18.42,-33.92,"South Africa",36,"Cape Town"],havana:[-82.37,23.11,"Cuba",36,"Havana"],addisababa:[38.75,9.03,"Ethiopia",36,"Addis Ababa"],marrakesh:[-7.99,31.63,"Morocco",36,"Marrakesh"],victoriafalls:[25.86,-17.92,"Zimbabwe",36,"Victoria Falls"],serengeti:[34.83,-2.33,"Tanzania",36,"Serengeti"],niagara:[-79.07,43.08,"Canada",36,"Niagara Falls"],yellowstone:[-110.59,44.43,"United States of America",36,"Yellowstone"],eiffeltower:[2.29,48.86,"France",36,"Eiffel Tower"],statueofliberty:[-74.04,40.69,"United States of America",36,"Statue of Liberty"],alhambra:[-3.59,37.18,"Spain",36,"Alhambra"]})});

ADDART({id:"shanghai",t:"Shanghai",c:"Countries and Places",i:"🌆",w:"Shanghai",r:["chinacountry","megacities","trade","opium","skyscrapers"],
p:[["China’s biggest city","Shanghai is China’s largest city and its leading center of finance and trade."],["A great port","It has the busiest container port in the world."],["Old and new","Its colonial-era Bund faces the skyscrapers of Pudong across the river."]],
l:"Shanghai is the largest city in China, with nearly 25 million people, and one of the most populous cities in the world. It lies on China’s east coast where the Yangtze River meets the East China Sea, on the banks of the Huangpu River. Once a market town, it was opened to foreign trade in 1842 after the First Opium War and grew into a cosmopolitan port with foreign-controlled districts. Today it is China’s financial and commercial capital and home to the world’s busiest container port. The historic waterfront known as the Bund, lined with early 20th-century buildings, faces the futuristic skyline of Pudong, including the Shanghai Tower, the tallest building in China.",
s:[["Treaty port","After the First Opium War, the Treaty of Nanking in 1842 forced China to open Shanghai to foreign trade. Britain, France and the United States set up settlements governed by foreigners. By the 1920s and 1930s, Shanghai was one of the world’s largest and most international cities, a center of banking, industry, publishing and film, but also of great poverty."],["War and revolution","Japan attacked Shanghai in 1932 and occupied it from 1937 to 1945. Shanghai also sheltered around 20,000 Jewish refugees fleeing Nazi Europe. After the Communists took power in 1949, foreign businesses left, and Shanghai became a center of state industry."],["Modern Shanghai","In 1990, the government decided to develop Pudong, then farmland east of the river, into a financial district. Within decades it filled with skyscrapers, including the Oriental Pearl Tower and the 632-meter Shanghai Tower. Shanghai now has one of the world’s largest metro systems and a magnetic levitation train that reaches 300 kilometers per hour."]],
k:[["Country","China"],["Population","Nearly 25 million"],["River","Huangpu"],["Tallest building","Shanghai Tower, 632 m"],["Port","World’s busiest container port"]],
d:[["1842","Opened to foreign trade"],["1920s–30s","An international boomtown"],["1937–45","Japanese occupation"],["1990","Development of Pudong begins"],["2004","The maglev train opens"],["2010","Shanghai hosts the World Expo"]],
s2:[["The Bund","The Bund is a riverside promenade lined with grand banks, hotels and offices built by foreign companies in the early 20th century in styles from Gothic to Art Deco. At night, its lit facades face the glittering towers of Pudong across the river, one of the most famous city views in the world."],["The maglev","Shanghai’s magnetic levitation train, opened in 2004, links the airport with the city. Using magnets instead of wheels, it floats above its track and reaches about 300 kilometers per hour, covering 30 kilometers in around eight minutes."]],
sp:["Xiaolongbao","Shanghai is famous for xiaolongbao, delicate steamed dumplings filled with pork and hot soup. Diners bite a small hole, sip the soup, then eat the dumpling, often with vinegar and ginger."],
g:[["Treaty port","A port opened to foreign trade by an unequal treaty"],["Bund","Shanghai’s historic waterfront"],["Maglev","A train that floats using magnets"],["Container port","A port that handles cargo in shipping containers"]],
f:["Shanghai has the world’s busiest container port.","The Shanghai Tower is 632 meters tall.","Pudong was mostly farmland in 1990."],
fun:"The name Shanghai means ‘upon the sea’.",
tl:"Ang Shanghai ang pinakamalaking lungsod sa Tsina at sentro ng pananalapi at kalakalan. Narito ang pinakaabalang container port sa mundo, at magkaharap sa ilog ang lumang Bund at ang matataas na gusali ng Pudong."});

ADDART({id:"losangeles",t:"Los Angeles",c:"Countries and Places",i:"🎬",w:"Los Angeles",r:["usacountry","cinema","megacities","migration","cars"],
p:[["City of Angels","Los Angeles is the second-largest city in the United States, in southern California."],["Home of Hollywood","It is the center of the American film and television industry."],["Diverse and spread out","It is famous for its sunshine, beaches, freeways and many cultures."]],
l:"Los Angeles, often called LA, is the second most populous city in the United States, with about 3.8 million people, and the center of a metropolitan area of around 13 million in southern California. Founded by Spanish settlers in 1781, it was part of Mexico until 1848 and grew rapidly after railroads arrived and oil was discovered. In the early 20th century, filmmakers moved to its Hollywood district, attracted by year-round sunshine, and it became the world capital of movies and entertainment. LA is known for its beaches, mountains, freeways and car culture, and is one of the most diverse cities in the world. It hosted the Olympic Games in 1932 and 1984 and will host them again in 2028.",
s:[["From pueblo to metropolis","In 1781, Spanish settlers of Indigenous, African and European descent founded El Pueblo de la Reina de los Ángeles near a Tongva village. The town passed to Mexico in 1821 and to the United States in 1848. Railroads, oil, citrus farming and later aircraft factories brought explosive growth."],["Hollywood","Filmmakers began arriving around 1910, drawn by sunshine, varied landscapes and cheap land. By the 1920s, Hollywood studios dominated world cinema. The Academy Awards, first held in 1929, are presented in Los Angeles, and the famous Hollywood Sign was built in 1923 as an advertisement."],["A sprawling city","Los Angeles spread outward across a huge basin, linked by an extensive freeway network built from the 1940s. It is known for traffic and once severe smog, which has improved greatly under clean-air laws. Earthquakes and wildfires are ongoing risks; in January 2025, wildfires destroyed thousands of homes in the region."]],
k:[["Country","United States"],["State","California"],["Population","About 3.8 million (city)"],["Founded","1781"],["Olympics","1932, 1984, 2028"]],
d:[["1781","Spanish settlers found the pueblo"],["1848","Becomes part of the United States"],["1910s","Filmmakers arrive in Hollywood"],["1923","The Hollywood Sign is built"],["1984","Hosts the Summer Olympics"],["2028","Will host the Olympics again"]],
s2:[["The Hollywood Sign","The Hollywood Sign originally read ‘HOLLYWOODLAND’ and was put up in 1923 to advertise a housing development. It was meant to last a year and a half. In 1949 the last four letters were removed, and the sign became a symbol of the film industry."],["Many cultures","Nearly half of Los Angeles residents are Latino, and the city has large communities from Mexico, Central America, Korea, China, Armenia, Iran and many other places. More than 200 languages are spoken in the county."]],
sp:["The Walk of Fame","Along Hollywood Boulevard, more than 2,700 brass stars set into the sidewalk honor actors, musicians and other entertainers. The Walk of Fame was created in 1960 and adds new stars each year."],
g:[["Pueblo","A Spanish word for a town or village"],["Freeway","A large highway without traffic lights"],["Smog","Air pollution made of smoke and fog"],["Studio","A company or site where films are made"]],
f:["Los Angeles was founded in 1781.","The Hollywood Sign once read ‘Hollywoodland’.","LA will host the Olympics for the third time in 2028."],
fun:"Los Angeles’ full original Spanish name was ‘The Town of the Queen of the Angels’.",
tl:"Ang Los Angeles ang ikalawang pinakamalaking lungsod sa Estados Unidos, sa timog California. Ito ang sentro ng industriya ng pelikula sa Hollywood at kilala sa araw, dalampasigan at maraming kultura."});

ADDART({id:"chicago",t:"Chicago",c:"Countries and Places",i:"🏙️",w:"Chicago",r:["usacountry","skyscrapers","jazz","indrev","rivers"],
p:[["The Windy City","Chicago is the third-largest city in the United States, on Lake Michigan."],["Birthplace of the skyscraper","The world’s first skyscraper was built there in 1885."],["A city of music","Chicago helped shape jazz, blues and house music."]],
l:"Chicago is the third most populous city in the United States, with about 2.7 million people, located in the state of Illinois on the southwestern shore of Lake Michigan. It grew rapidly in the 19th century as a hub for railroads, shipping, grain, meatpacking and industry linking the eastern United States with the West. After the Great Chicago Fire of 1871 destroyed much of the city, it was rebuilt with bold new architecture, including the world’s first skyscraper. Chicago is known for its skyline, lakefront parks, museums, deep-dish pizza and its role in the history of jazz and blues. Its nickname, the Windy City, may come from its lake breezes or from its boastful politicians.",
s:[["A boomtown","Chicago was incorporated as a city in 1837 with about 4,000 people. Canals and railroads made it the crossroads of the nation, and by 1890 it had over a million residents. Immigrants from Germany, Ireland, Poland, Italy and elsewhere came to work in its stockyards, factories and rail yards."],["Fire and rebuilding","In October 1871, the Great Chicago Fire burned for over a day, destroying about 17,000 buildings and leaving around 100,000 people homeless. Architects rushed to rebuild, and in 1885 the ten-story Home Insurance Building, with a steel frame, became the first skyscraper. Chicago also reversed the flow of its river in 1900 to carry sewage away from the lake."],["Music and culture","During the Great Migration, many Black Americans moved from the South to Chicago, bringing blues and jazz, and the city became famous for electric Chicago blues. House music was born in Chicago clubs in the 1980s. The city is home to the Art Institute of Chicago and the Field Museum."]],
k:[["Country","United States"],["State","Illinois"],["Population","About 2.7 million"],["Lake","Michigan"],["First skyscraper","Home Insurance Building, 1885"]],
d:[["1837","Chicago becomes a city"],["1871","The Great Chicago Fire"],["1885","The first skyscraper is built"],["1893","World’s Columbian Exposition"],["1900","The Chicago River’s flow is reversed"],["1973","Sears (Willis) Tower completed"]],
s2:[["The Ferris wheel","For the World’s Columbian Exposition of 1893, engineer George Ferris built a giant rotating wheel 80 meters tall, as America’s answer to the Eiffel Tower. It carried over 2,000 passengers at a time and gave its name to Ferris wheels everywhere."],["Dyeing the river green","Every year for St Patrick’s Day, Chicago dyes its river bright green, a tradition that began in 1962. The dye lasts only a few hours."]],
sp:["Cloud Gate","Cloud Gate, a huge stainless steel sculpture in Millennium Park nicknamed ‘the Bean’, reflects the skyline and visitors like a giant curved mirror. Designed by artist Anish Kapoor, it was completed in 2006."],
g:[["Skyscraper","A very tall building with many floors"],["Stockyard","An area where livestock are kept before sale or slaughter"],["Great Migration","The movement of millions of Black Americans from the South to northern cities"],["Blues","A style of music rooted in African American experience"]],
f:["Chicago reversed the direction of its river in 1900.","The first Ferris wheel was built in Chicago.","The first skyscraper was built in Chicago in 1885."],
fun:"Chicago’s river is dyed green every St Patrick’s Day.",
tl:"Ang Chicago ang ikatlong pinakamalaking lungsod sa Estados Unidos, sa tabi ng Lawa ng Michigan. Dito itinayo ang unang skyscraper noong 1885, at mahalaga ito sa kasaysayan ng jazz at blues."});

ADDART({id:"amsterdam",t:"Amsterdam",c:"Countries and Places",i:"🚲",w:"Amsterdam",r:["netherlandscountry","bicycle","trade","holocaust","floods"],
p:[["City of canals","Amsterdam is the capital of the Netherlands, famous for its canals and narrow houses."],["Golden Age","In the 1600s, it was one of the richest cities in the world."],["Bicycles everywhere","There are more bicycles than people in the city."]],
l:"Amsterdam is the capital and largest city of the Netherlands, with about 930,000 people. It began as a fishing village beside a dam on the Amstel River, which gave it its name. In the 17th century, the Dutch Golden Age, it became the center of global trade, finance and art, home to the Dutch East India Company and the world’s first modern stock exchange. Its ring of 17th-century canals, lined with tall, narrow merchant houses, is a UNESCO World Heritage Site. Amsterdam is known for its museums, including the Rijksmuseum and the Van Gogh Museum, the Anne Frank House, its tolerance and its cycling culture: there are more bicycles than residents.",
s:[["A city on a dam","Around 1270, people built a dam on the Amstel River, and a settlement grew around it, called Amstelredamme. Much of the city stands on land reclaimed from water, with buildings resting on wooden piles driven into the soft ground."],["The Golden Age","In the 1600s, Amsterdam was the busiest port in Europe. The Dutch East India Company, founded in 1602, traded across Asia, and the Amsterdam stock exchange was the first to trade shares regularly. Wealth flowed into art, and painters such as Rembrandt worked there. The trade also involved colonial violence and the slave trade."],["Modern Amsterdam","During the Second World War, the Nazis occupied the city and deported most of its large Jewish population; Anne Frank hid in a secret annex there before her capture. Today Amsterdam is a lively, international city known for its liberal culture, festivals and design."]],
k:[["Country","Netherlands"],["Population","About 930,000"],["River","Amstel"],["Canal ring","UNESCO site since 2010"],["Famous museum","Rijksmuseum"]],
d:[["c.1270","A dam is built on the Amstel"],["1602","The Dutch East India Company is founded"],["1613","Construction of the canal ring begins"],["1642","Rembrandt paints ‘The Night Watch’"],["1942–44","Anne Frank hides in the secret annex"],["2010","The canal ring is listed by UNESCO"]],
s2:[["The canal houses","Amsterdam’s canal houses are tall and narrow because property was once taxed by the width of its front. Many lean forward slightly and have hooks at the top, used with ropes to lift furniture through the windows, since the staircases are too steep and narrow."],["The Anne Frank House","Anne Frank, a Jewish girl, hid with her family in a secret annex behind a bookcase in a canal house from 1942 until they were discovered in 1944. She died in a concentration camp in 1945. Her diary, published after the war, became one of the most read books in the world, and the house is now a museum."]],
sp:["Cycling city","Amsterdam has over 500 kilometers of cycle paths and an estimated 880,000 bicycles. Thousands of bikes are fished out of the canals every year."],
g:[["Canal","An artificial waterway"],["Golden Age","A period of great wealth and achievement"],["Stock exchange","A market where shares in companies are traded"],["Reclaimed land","Land created from water or marshes"]],
f:["Amsterdam is named after a dam on the Amstel River.","There are more bicycles than people in Amsterdam.","Many canal houses have hooks for lifting furniture."],
fun:"Amsterdam has more canals than Venice, with about 100 kilometers of waterways.",
tl:"Ang Amsterdam ang kabisera ng Netherlands, kilala sa mga kanal at makikitid na bahay. Isa ito sa pinakamayayamang lungsod noong 1600, at mas marami ang bisikleta kaysa tao rito."});

ADDART({id:"barcelona",t:"Barcelona",c:"Countries and Places",i:"⛪",w:"Barcelona",r:["spaincountry","architecture","soccer","olymp","tourism"],
p:[["Catalonia’s capital","Barcelona is the capital of Catalonia and Spain’s second-largest city."],["Gaudí’s city","It is famous for the fantastical buildings of architect Antoni Gaudí."],["Sea and sport","It has Mediterranean beaches and one of the world’s most famous football clubs."]],
l:"Barcelona is the capital of Catalonia, an autonomous community in northeastern Spain, and the country’s second-largest city, with about 1.7 million people. It lies on the Mediterranean coast between the sea and the Collserola hills. Founded as a Roman town, it grew into a major Mediterranean trading power in the Middle Ages and an industrial center in the 19th century. Barcelona is famous for its architecture, especially the colorful, curving works of Antoni Gaudí, including the Sagrada Família, Park Güell and Casa Batlló. Its people speak Catalan as well as Spanish. The 1992 Olympic Games transformed the city, and FC Barcelona is one of the most successful football clubs in the world.",
s:[["Roman to medieval city","The Romans founded a colony called Barcino on the site in the 1st century BC. In the Middle Ages, Barcelona was the capital of the County of Barcelona and a center of the Crown of Aragon, whose fleets traded across the Mediterranean. Its Gothic Quarter preserves narrow medieval streets and a cathedral."],["Modernisme","In the late 19th and early 20th centuries, Barcelona expanded with a new grid district, the Eixample, designed by Ildefons Cerdà, with octagonal blocks. Wealthy industrialists commissioned architects of the Catalan Modernisme movement, especially Gaudí, to build houses and churches full of curves, mosaics and natural forms."],["Olympics and tourism","The 1992 Olympics led to new beaches, a waterfront and transport. Barcelona became one of Europe’s most visited cities, and residents have since debated how to manage overtourism, rising rents and holiday rentals."]],
k:[["Country","Spain"],["Region","Catalonia (capital)"],["Population","About 1.7 million"],["Languages","Catalan and Spanish"],["Famous architect","Antoni Gaudí"]],
d:[["1st century BC","Romans found Barcino"],["1860","The Eixample expansion plan begins"],["1882","Construction of the Sagrada Família starts"],["1899","FC Barcelona is founded"],["1992","Barcelona hosts the Olympics"],["2026","Centenary of Gaudí’s death"]],
s2:[["Park Güell","Park Güell, designed by Gaudí, was planned as a housing estate in the early 1900s but became a public park. It is famous for its wavy bench covered in broken tile mosaics, called trencadís, its gingerbread-like gatehouses and a colorful mosaic lizard."],["Human towers","At festivals in Catalonia, teams called colles build castells, human towers up to ten levels high, with a child climbing to the top. UNESCO recognized the tradition as intangible cultural heritage in 2010."]],
sp:["La Rambla","La Rambla is a famous tree-lined avenue running from the city center to the old port, crowded with walkers, cafés, flower stalls and street performers. It passes the Boqueria, one of Europe’s best-known food markets."],
g:[["Catalan","The language of Catalonia"],["Modernisme","A Catalan art and architecture movement around 1900"],["Trencadís","A mosaic made of broken tiles"],["Castell","A Catalan human tower"]],
f:["Barcelona was founded by the Romans as Barcino.","Catalan and Spanish are both spoken in Barcelona.","The Eixample district has octagonal city blocks."],
fun:"Barcelona’s human towers can be ten levels high, with a child at the very top.",
tl:"Ang Barcelona ang kabisera ng Catalonia at ikalawang pinakamalaking lungsod ng Espanya. Tanyag ito sa kakaibang mga gusali ni Antoni Gaudí, sa dalampasigan at sa koponang FC Barcelona."});

ADDART({id:"vienna",t:"Vienna",c:"Countries and Places",i:"🎻",w:"Vienna",r:["austriacountry","mozart","opera","ottoman","coffee"],
p:[["Austria’s capital","Vienna is the capital of Austria, on the Danube River."],["City of music","Mozart, Beethoven, Haydn and Schubert worked there."],["Imperial grandeur","It was the capital of the Habsburg Empire for centuries."]],
l:"Vienna is the capital and largest city of Austria, with about 2 million people, located on the Danube River in the east of the country. For over six centuries, it was the seat of the Habsburg dynasty, which ruled a vast empire in central Europe, and it is filled with palaces, churches and grand boulevards. Vienna is world-famous for classical music: composers including Mozart, Haydn, Beethoven, Schubert, Brahms and the Strauss family lived and worked there. It is also known for its coffee houses, the waltz, the Vienna Boys’ Choir and the Spanish Riding School. Vienna regularly ranks among the most livable cities in the world and hosts several United Nations organizations.",
s:[["Imperial capital","Vienna became the seat of the Habsburgs in the 13th century. Their empire eventually stretched across much of central Europe. Ottoman armies besieged the city in 1529 and again in 1683, when a relief army led by King Jan III Sobieski of Poland defeated them. The Habsburgs built the Hofburg palace and the summer palace of Schönbrunn."],["City of music","In the 18th and 19th centuries, Vienna was the musical capital of Europe. Mozart composed many of his greatest works there, Beethoven lived there for 35 years, and Johann Strauss II made the waltz famous with pieces such as ‘The Blue Danube’. The Vienna State Opera and the Vienna Philharmonic are among the world’s most famous."],["Ideas and modern Vienna","Around 1900, Vienna was a center of new ideas in art, architecture and science, home to painter Gustav Klimt and Sigmund Freud, the founder of psychoanalysis. After the empire collapsed in 1918, Vienna became capital of the small Republic of Austria. Today it is known for its public housing, green spaces and high quality of life."]],
k:[["Country","Austria"],["Population","About 2 million"],["River","Danube"],["Former empire","Habsburg"],["Famous palace","Schönbrunn"]],
d:[["1278","The Habsburgs take control"],["1529","First Ottoman siege"],["1683","Second Ottoman siege defeated"],["1781","Mozart settles in Vienna"],["1918","The Habsburg Empire collapses"],["1979","The Vienna International Centre for the UN opens"]],
s2:[["Viennese coffee houses","Vienna’s coffee houses, where people sit for hours reading newspapers over a coffee and a slice of cake such as Sachertorte, have been part of city life since the late 1600s. UNESCO recognized Viennese coffee house culture as intangible heritage in 2011."],["The New Year’s Concert","Every 1 January, the Vienna Philharmonic performs a New Year’s Concert of waltzes and polkas by the Strauss family in the golden hall of the Musikverein, broadcast to tens of millions of viewers in about 90 countries."]],
sp:["Schönbrunn Palace","Schönbrunn Palace, the Habsburgs’ summer residence, has more than 1,400 rooms and vast gardens. It also contains the world’s oldest zoo still operating, founded in 1752."],
g:[["Habsburg","A royal family that ruled much of Europe for centuries"],["Waltz","A ballroom dance in three-four time"],["Siege","Surrounding a city to capture it"],["Psychoanalysis","A method of treating the mind developed by Freud"]],
f:["Vienna’s Schönbrunn Zoo, founded in 1752, is the oldest zoo still operating.","Beethoven lived in Vienna for 35 years.","Vienna hosts several United Nations offices."],
fun:"Beethoven moved home in Vienna dozens of times.",
tl:"Ang Vienna ang kabisera ng Austria, sa tabi ng Ilog Danube. Lungsod ito ng musika kung saan nanirahan sina Mozart at Beethoven, at kabisera ng Imperyong Habsburg nang maraming siglo."});

ADDART({id:"prague",t:"Prague",c:"Countries and Places",i:"🏰",w:"Prague",r:["castles","gothic","coldwar","medieurope","clocks"],
p:[["The city of a hundred spires","Prague is the capital of the Czech Republic, famous for its beautiful old center."],["A royal capital","It was the seat of Bohemian kings and Holy Roman emperors."],["Spared in war","Its medieval and baroque buildings survived largely intact."]],
l:"Prague is the capital and largest city of the Czech Republic (Czechia), with about 1.4 million people, on the Vltava River in central Europe. Known as ‘the city of a hundred spires’, it has one of the best-preserved historic centers in Europe, with Romanesque, Gothic, Renaissance and Baroque buildings. It was the seat of the kings of Bohemia and, under Emperor Charles IV in the 14th century, capital of the Holy Roman Empire. Prague Castle, the Charles Bridge, the Old Town Square and its astronomical clock draw millions of visitors. The city was the scene of the Prague Spring of 1968 and the peaceful Velvet Revolution of 1989.",
s:[["Golden Prague","Under Charles IV, who ruled in the 14th century, Prague became one of Europe’s largest cities. He founded Charles University in 1348, the oldest in central Europe, and began the Charles Bridge and St Vitus Cathedral. Prague Castle, overlooking the river, is said to be the largest ancient castle complex in the world."],["Reformation and empire","In the early 1400s, the preacher Jan Hus called for church reform and was burned at the stake, sparking the Hussite wars. In 1618, Protestant nobles threw imperial officials out of a castle window, an event that helped start the Thirty Years’ War. Prague later came under Habsburg rule."],["The 20th century","Prague became the capital of independent Czechoslovakia in 1918. It was occupied by Nazi Germany in 1939 and came under communist rule in 1948. In 1968, reforms known as the Prague Spring were crushed by Soviet-led tanks. In 1989, mass peaceful protests, the Velvet Revolution, ended communist rule, and in 1993 Czechoslovakia split peacefully into two countries."]],
k:[["Country","Czech Republic (Czechia)"],["Population","About 1.4 million"],["River","Vltava"],["Oldest university","Charles University, 1348"],["Famous clock","The astronomical clock, 1410"]],
d:[["c.880","Prague Castle is founded"],["1348","Charles University is founded"],["1357","Construction of the Charles Bridge begins"],["1410","The astronomical clock is installed"],["1968","The Prague Spring"],["1989","The Velvet Revolution"]],
s2:[["The astronomical clock","The Prague astronomical clock, installed on the Old Town Hall in 1410, is the oldest astronomical clock still working. It shows the positions of the sun and moon and other details, and every hour figures of the apostles parade past its windows while a skeleton rings a bell."],["The Charles Bridge","The Charles Bridge, a stone bridge over the Vltava begun in 1357, is lined with 30 statues of saints. According to legend, touching the plaque on the statue of St John of Nepomuk brings good luck and ensures a return to Prague."]],
sp:["The Velvet Revolution","In November 1989, students and citizens filled Wenceslas Square in peaceful protests, jingling keys to tell the communist leaders it was time to go. Within weeks the government resigned, and the playwright and dissident Václav Havel became president."],
g:[["Spire","A tall pointed structure on top of a building"],["Bohemia","A historic region forming much of today’s Czech Republic"],["Astronomical clock","A clock that shows the positions of the sun, moon and stars"],["Velvet Revolution","The peaceful end of communist rule in Czechoslovakia in 1989"]],
f:["Prague’s astronomical clock has worked since 1410.","Charles University was founded in 1348.","The Charles Bridge has 30 statues."],
fun:"Prague Castle is often said to be the largest ancient castle complex in the world.",
tl:"Ang Prague ang kabisera ng Czech Republic, tanyag sa magandang lumang sentro nito na tinatawag na ‘lungsod ng sandaang tore’. Dito naganap ang mapayapang Velvet Revolution noong 1989."});

ADDART({id:"stpetersburg",t:"St Petersburg",c:"Countries and Places",i:"🏛️",w:"Saint Petersburg",r:["russiacountry","russrev","moscow","museums","ww2"],
p:[["Peter the Great’s city","St Petersburg was founded in 1703 by Tsar Peter the Great."],["Russia’s former capital","It was Russia’s capital for about two centuries."],["Palaces and canals","It is famous for its grand palaces, canals and the Hermitage Museum."]],
l:"St Petersburg is Russia’s second-largest city, with about 5.6 million people, located on the Neva River where it flows into the Gulf of Finland on the Baltic Sea. It was founded in 1703 by Tsar Peter the Great, who wanted a ‘window to Europe’, and served as Russia’s capital from 1712 to 1918. Built on marshy islands and crossed by canals and rivers, it is famous for its grand European-style architecture, including the Winter Palace, which houses the Hermitage Museum. The city was renamed Petrograd in 1914 and Leningrad in 1924, before reclaiming its original name in 1991. It was the birthplace of the Russian Revolution of 1917 and endured a terrible siege in the Second World War.",
s:[["A city built from nothing","Peter the Great founded the city on swampy land captured from Sweden. Tens of thousands of laborers, many forced, drained marshes and built on wooden piles, and many died. Peter invited European architects, and the city was laid out with straight avenues, canals and grand palaces, unlike older Russian cities."],["Imperial capital","As capital, St Petersburg became the center of Russian government, culture and science. Empress Catherine the Great began the art collection of the Hermitage, which grew into one of the largest museums in the world. Writers such as Pushkin and Dostoevsky set famous works there."],["Revolution and siege","In 1917, protests in the city, then called Petrograd, overthrew the tsar, and the Bolsheviks seized power there in October. In the Second World War, German forces besieged Leningrad for nearly 900 days, from 1941 to 1944; around a million civilians died, mostly from starvation."]],
k:[["Country","Russia"],["Population","About 5.6 million"],["River","Neva"],["Founded","1703, by Peter the Great"],["Former names","Petrograd, Leningrad"]],
d:[["1703","Peter the Great founds the city"],["1712","Becomes Russia’s capital"],["1764","The Hermitage collection begins"],["1917","The Russian Revolution"],["1941–44","The Siege of Leningrad"],["1991","The name St Petersburg is restored"]],
s2:[["The white nights","Because St Petersburg lies so far north, in early summer the sun sets for only a few hours and the sky never gets fully dark. The city celebrates these ‘white nights’ with festivals, concerts and late-night walks."],["Raising the bridges","Many bridges over the Neva open at night so that ships can pass between the Baltic Sea and inland waterways. Crowds gather to watch the bridges rise, and anyone caught on the wrong side must wait until morning."]],
sp:["The Hermitage","The State Hermitage Museum, based in the Winter Palace, holds around 3 million objects, from Egyptian antiquities to paintings by Rembrandt, Leonardo da Vinci and Picasso. A group of cats has lived in the museum for centuries, once kept to catch mice."],
g:[["Tsar","The title of Russia’s emperors"],["Siege","Surrounding a city to force it to surrender"],["White nights","Summer nights when the sky stays light"],["Hermitage","One of the world’s largest art museums"]],
f:["St Petersburg was founded in 1703.","The city has had three names.","The Hermitage keeps a group of museum cats."],
fun:"St Petersburg has more than 300 bridges.",
tl:"Ang St Petersburg ay itinatag ni Tsar Peter the Great noong 1703 at naging kabisera ng Russia nang mga dalawang siglo. Tanyag ito sa malalaking palasyo, kanal at Hermitage Museum."});

ADDART({id:"delhi",t:"Delhi",c:"Countries and Places",i:"🕌",w:"Delhi",r:["indiacountry","mughal","partition","megacities","tajmahal"],
p:[["India’s capital region","Delhi is home to New Delhi, the capital of India."],["Many cities in one","Several empires built capitals on the same site over a thousand years."],["A megacity","Its metropolitan area is one of the most populous in the world."]],
l:"Delhi, officially the National Capital Territory of Delhi, is a city and territory in northern India that contains New Delhi, the country’s capital. Its wider urban area, with over 30 million people, is one of the largest in the world. Delhi lies on the Yamuna River and has been the site of many cities and capitals over more than a thousand years, built by Rajput kings, the Delhi Sultanate, the Mughal Empire and the British. Its monuments include the Qutb Minar, the Red Fort, the Jama Masjid, Humayun’s Tomb and the India Gate. Delhi is India’s political center and a major hub of commerce, education and culture, but faces serious problems with air pollution.",
s:[["Seven cities","Historians often say Delhi has been built as ‘seven cities’ or more. The Delhi Sultanate, founded in 1206, built the Qutb Minar. In the 1600s, the Mughal emperor Shah Jahan built a new walled city, Shahjahanabad, now Old Delhi, with the Red Fort and the Jama Masjid, one of India’s largest mosques."],["New Delhi","In 1911, the British moved the capital of India from Calcutta to Delhi and built New Delhi, designed by architects Edwin Lutyens and Herbert Baker, with wide avenues and grand government buildings. It was inaugurated in 1931. On 15 August 1947, Prime Minister Nehru raised India’s flag at the Red Fort at independence."],["Modern Delhi","Partition in 1947 brought hundreds of thousands of refugees to Delhi. The city has grown enormously, with a large metro system opened in 2002. Smoke from crop burning, traffic and industry make winter air pollution among the worst in the world."]],
k:[["Country","India"],["Capital","New Delhi"],["Population","Over 30 million (urban area)"],["River","Yamuna"],["Famous tower","Qutb Minar, 73 m"]],
d:[["1206","The Delhi Sultanate is founded"],["1648","Shah Jahan completes the Red Fort"],["1911","The British move India’s capital to Delhi"],["1931","New Delhi is inaugurated"],["1947","India’s independence is celebrated at the Red Fort"],["2002","The Delhi Metro opens"]],
s2:[["Qutb Minar","The Qutb Minar, begun around 1199, is a tapering tower of red sandstone and marble about 73 meters tall, covered in carved inscriptions. Nearby stands an iron pillar over 1,600 years old that has barely rusted, a marvel of ancient Indian metalworking."],["Chandni Chowk","Chandni Chowk, in Old Delhi, is one of India’s oldest and busiest markets, laid out in the 17th century. Its narrow lanes are packed with shops selling spices, fabrics, jewelry and famous street food such as parathas and jalebis."]],
sp:["Humayun’s Tomb","Humayun’s Tomb, built in the 1560s for the second Mughal emperor, was the first great garden tomb in India. Its red sandstone and white marble design, set in a square garden divided by water channels, inspired the later Taj Mahal."],
g:[["Sultanate","A state ruled by a sultan"],["Mughal","A dynasty that ruled much of India from 1526"],["Territory","An area governed differently from states"],["Partition","The division of British India in 1947"]],
f:["Delhi’s iron pillar is over 1,600 years old and has barely rusted.","The Qutb Minar is about 73 meters tall.","New Delhi was inaugurated in 1931."],
fun:"Delhi has been the capital of many empires, so it is sometimes called a ‘city of cities’.",
tl:"Narito sa Delhi ang New Delhi, ang kabisera ng India. Ilang imperyo ang nagtayo ng kabisera sa iisang lugar sa loob ng isang libong taon, at isa ito sa pinakamataong lungsod sa mundo."});

ADDART({id:"capetown",t:"Cape Town",c:"Countries and Places",i:"⛰️",w:"Cape Town",r:["southafricacountry","apartheid","mandela","droughts","ships"],
p:[["Mother City","Cape Town is South Africa’s oldest city, founded in 1652."],["Table Mountain","A flat-topped mountain rises behind the city."],["Where two oceans meet","The nearby Cape Peninsula looks out over the Atlantic and Indian Oceans."]],
l:"Cape Town is a city in southwestern South Africa, the country’s legislative capital, where Parliament sits, and its second most populous city, with over 4.7 million people in its metropolitan area. It lies on Table Bay, beneath the flat-topped Table Mountain, near the southern tip of Africa. Founded in 1652 by the Dutch East India Company as a supply station for ships sailing to Asia, it is South Africa’s oldest city and is nicknamed the ‘Mother City’. Its history includes colonial rule, slavery and apartheid; Nelson Mandela was imprisoned on nearby Robben Island. Today it is known for its natural beauty, beaches, vineyards, wildlife including penguins, and its diverse cultures.",
s:[["A refreshment station","Indigenous Khoekhoe and San peoples lived in the area for thousands of years. In 1652, Jan van Riebeeck of the Dutch East India Company set up a station to supply passing ships with fresh food and water. Enslaved people brought from Asia and Africa built much of the colony. Britain took control in the early 1800s."],["Apartheid and resistance","Under apartheid, laws forced people classified as non-white out of central areas such as District Six, whose homes were bulldozed. Robben Island, in Table Bay, held political prisoners, including Nelson Mandela for 18 years. After his release in 1990, Mandela gave his first speech from the balcony of Cape Town City Hall."],["Modern Cape Town","Cape Town is a center of tourism, film and technology. In 2018, after a severe drought, the city came close to ‘Day Zero’, when taps would run dry, but residents cut water use dramatically. Large inequalities remain between wealthy suburbs and crowded townships."]],
k:[["Country","South Africa"],["Role","Legislative capital"],["Population","Over 4.7 million (metro)"],["Founded","1652"],["Landmark","Table Mountain"]],
d:[["1652","Founded as a Dutch supply station"],["1806","Britain takes control"],["1834","Slavery is abolished in the colony"],["1966","District Six is declared ‘whites only’"],["1990","Mandela speaks at City Hall after release"],["2018","‘Day Zero’ water crisis averted"]],
s2:[["Table Mountain","Table Mountain, about 1,085 meters high, has a flat top about 3 kilometers wide. When clouds pour over its edge, locals say the ‘tablecloth’ is on. A cable car carries visitors to the top. Its slopes are part of the Cape Floral Kingdom, one of the richest plant regions on Earth."],["Penguins on the beach","At Boulders Beach, south of the city, a colony of African penguins nests among the granite rocks, and visitors can watch them from boardwalks. The species is endangered."]],
sp:["Robben Island","Robben Island, about 7 kilometers offshore, was used for centuries as a prison and place of exile. Former political prisoners now guide visitors through its prison, including the small cell where Mandela was held. It became a UNESCO World Heritage Site in 1999."],
g:[["Legislative capital","The city where a country’s parliament meets"],["Township","An area created for non-white people under apartheid"],["Cape Floral Kingdom","A small region with an extraordinary variety of plants"],["Supply station","A place where ships stop for food and water"]],
f:["Cape Town is South Africa’s oldest city.","Nelson Mandela was held on Robben Island for 18 years.","African penguins live on beaches near Cape Town."],
fun:"South Africa has three capital cities: Pretoria, Cape Town and Bloemfontein.",
tl:"Ang Cape Town ang pinakamatandang lungsod ng South Africa, itinatag noong 1652. Nasa likod nito ang patag na Table Mountain, at sa malapit na Robben Island ikinulong si Nelson Mandela."});

ADDART({id:"havana",t:"Havana",c:"Countries and Places",i:"🚗",w:"Havana",r:["cubacountry","coldwar","cubancrisis","latinind","cars"],
p:[["Cuba’s capital","Havana is the capital and largest city of Cuba."],["Colonial treasure","Its old town and forts were key to Spain’s treasure fleets."],["Classic cars","Its streets are famous for 1950s American cars still in use."]],
l:"Havana is the capital and largest city of Cuba, with about 2.1 million people, located on the island’s northern coast. Founded by the Spanish in the early 16th century and moved to its present site in 1519, it grew into the most important port of the Spanish Caribbean, where treasure fleets gathered before crossing the Atlantic. Its historic center, Old Havana, with colonial plazas, churches and forts, is a UNESCO World Heritage Site. After the Cuban Revolution of 1959, the city became the capital of a communist state. Havana is famous for its music, colorful buildings, seaside boulevard called the Malecón and the vintage American cars that still fill its streets.",
s:[["Port of the treasure fleets","From the 16th century, Spanish ships carrying silver and gold from the Americas gathered in Havana’s sheltered harbor to sail together to Spain. To protect it from pirates and rival powers, Spain built massive forts, including El Morro and La Cabaña. Britain captured the city briefly in 1762."],["Sugar, music and revolution","In the 19th and early 20th centuries, Havana grew rich from sugar and tobacco, and later became a destination for American tourists. Its music, including son, mambo and cha-cha-chá, spread worldwide. In 1959, revolutionaries led by Fidel Castro took power, and the city became the center of a communist government aligned with the Soviet Union."],["Havana today","The US trade embargo and economic hardship left many buildings in disrepair, though parts of Old Havana have been carefully restored. Cubans have kept old cars running with ingenuity. Shortages of food, fuel and electricity have caused hardship in recent years, and many people have emigrated."]],
k:[["Country","Cuba"],["Population","About 2.1 million"],["Founded","1519 at its present site"],["Old town","UNESCO site since 1982"],["Seafront","The Malecón"]],
d:[["1519","Havana moves to its present site"],["1589","El Morro fortress begun"],["1762","Britain briefly captures the city"],["1902","Capital of independent Cuba"],["1959","The Cuban Revolution"],["1982","Old Havana listed by UNESCO"]],
s2:[["The classic cars","Before 1959, Cubans imported many American cars. After the revolution and the US embargo, new cars became almost impossible to buy, so owners kept their 1940s and 1950s Chevrolets, Fords and Buicks running for decades, often with homemade parts. Today many serve as taxis for tourists."],["The Malecón","The Malecón is an 8-kilometer seawall and boulevard along Havana’s coast. In the evenings, people gather to talk, fish, play music and watch the sunset, and during storms, waves crash over the wall onto the road."]],
sp:["The cannon shot","Every night at 9 pm, soldiers in 18th-century uniforms fire a cannon from the La Cabaña fortress. The ceremony recalls the colonial era, when the shot signaled the closing of the city gates and the chain across the harbor."],
g:[["Embargo","An official ban on trade with a country"],["Malecón","Havana’s seaside boulevard"],["Son","A Cuban style of music and dance"],["Treasure fleet","A convoy of ships carrying silver and gold to Spain"]],
f:["Havana’s old town is a UNESCO World Heritage Site.","A cannon is fired in Havana every night at 9 pm.","Many 1950s American cars still drive in Havana."],
fun:"Some of Havana’s classic cars are more than 70 years old and still in daily use.",
tl:"Ang Havana ang kabisera at pinakamalaking lungsod ng Cuba. Mahalaga ang lumang bayan at mga kuta nito sa mga barkong may kayamanan ng Espanya, at tanyag ito sa mga lumang kotseng Amerikano mula dekada 1950."});

ADDART({id:"addisababa",t:"Addis Ababa",c:"Countries and Places",i:"☕",w:"Addis Ababa",r:["ethiopiacountry","africanunion","coffee","aksum","africacolon"],
p:[["Ethiopia’s capital","Addis Ababa is the capital and largest city of Ethiopia."],["High in the mountains","At about 2,355 meters, it is one of the highest capital cities in the world."],["Africa’s diplomatic capital","It is home to the headquarters of the African Union."]],
l:"Addis Ababa, whose name means ‘new flower’ in Amharic, is the capital and largest city of Ethiopia, with over 5 million people. It lies in the highlands at about 2,355 meters above sea level, giving it a mild climate despite being near the equator. Founded in 1886 by Emperor Menelik II and Empress Taytu, it grew rapidly as the capital of an ancient country that was never colonized, apart from a brief Italian occupation. Today Addis Ababa is the headquarters of the African Union and the UN Economic Commission for Africa, earning it the nickname ‘the political capital of Africa’. It is known for its coffee culture, music, the National Museum and its fast-growing skyline.",
s:[["A new capital","Empress Taytu chose the site near hot springs, and Emperor Menelik II made it his capital in 1886. Eucalyptus trees imported from Australia were planted to provide firewood and building material, and they still surround the city. A railway to Djibouti on the Red Sea, completed in 1917, connected it to the coast."],["Independence and occupation","Ethiopia defeated an Italian invasion at the Battle of Adwa in 1896, remaining independent while most of Africa was colonized. Italy occupied the country from 1936 to 1941, but Emperor Haile Selassie returned. He made Addis Ababa a center of African unity, hosting the founding of the Organisation of African Unity in 1963."],["A growing city","Since the 2000s, Addis Ababa has grown rapidly, with new roads, towers and Sub-Saharan Africa’s first light rail system, opened in 2015. Ethiopian Airlines, based there, is one of Africa’s largest airlines. The city faces challenges of housing, jobs and the impact of conflicts elsewhere in the country."]],
k:[["Country","Ethiopia"],["Population","Over 5 million"],["Altitude","About 2,355 m"],["Founded","1886"],["Name means","‘New flower’"]],
d:[["1886","Founded by Menelik II and Taytu"],["1896","Ethiopia wins the Battle of Adwa"],["1917","Railway to Djibouti completed"],["1936–41","Italian occupation"],["1963","Organisation of African Unity founded here"],["2015","Light rail system opens"]],
s2:[["Lucy","Ethiopia’s National Museum in Addis Ababa displays a cast of ‘Lucy’, a 3.2-million-year-old skeleton of an early human relative, Australopithecus afarensis, found in Ethiopia in 1974, along with other important fossils. The original bones are kept safely in the museum’s vaults."],["The coffee ceremony","Coffee is believed to have originated in Ethiopia. In the traditional coffee ceremony, green beans are roasted in a pan, ground by hand and brewed in a clay pot called a jebena, then served in three rounds. It can last an hour or more and is a time for conversation."]],
sp:["The African Union headquarters","The African Union Conference Center, opened in 2012, is a 20-story tower that dominates part of the skyline. Leaders from across the continent meet there for summits. Outside stands a statue of Kwame Nkrumah, a founding figure of African unity."],
g:[["Amharic","Ethiopia’s main working language"],["Highlands","High, mountainous land"],["Jebena","A clay coffee pot used in Ethiopia"],["Headquarters","The main office of an organization"]],
f:["Addis Ababa means ‘new flower’.","It is one of the highest capital cities in the world.","Ethiopia was never colonized, apart from a short Italian occupation."],
fun:"Addis Ababa’s many eucalyptus trees came from Australia over a century ago.",
tl:"Ang Addis Ababa ang kabisera at pinakamalaking lungsod ng Ethiopia, nasa mga 2,355 metro ang taas. Dito matatagpuan ang punong-tanggapan ng African Union kaya tinatawag itong kabiserang pampulitika ng Africa."});

ADDART({id:"marrakesh",t:"Marrakesh",c:"Countries and Places",i:"🕌",w:"Marrakesh",r:["moroccocountry","islamicart","desert","tourism","trade"],
p:[["The Red City","Marrakesh is a historic city in Morocco, known for its red walls."],["A great square","Its main square, Jemaa el-Fnaa, fills with performers and food stalls every evening."],["Gateway to the desert","It lies near the Atlas Mountains and the Sahara."]],
l:"Marrakesh is a major city in Morocco, with about 1 million people, at the foot of the Atlas Mountains. Founded in 1070 by the Almoravid dynasty, it served several times as the capital of empires that ruled Morocco and parts of Spain and West Africa, and it gave the country its name in many languages. Its old walled medina, a UNESCO World Heritage Site, is known as the Red City for the color of its earthen walls and buildings. Marrakesh is famous for the Koutoubia Mosque, its souks, palaces and gardens, and above all the Jemaa el-Fnaa square, where storytellers, musicians, snake charmers and food stalls gather each evening.",
s:[["Imperial city","The Almoravids, Berber rulers from the Sahara, founded Marrakesh as their capital. Their successors, the Almohads, built the Koutoubia Mosque in the 12th century. Later, the Saadian dynasty made it their capital in the 16th century and built lavish palaces and tombs."],["The medina","Inside walls about 19 kilometers long lies the medina, a maze of narrow streets and alleys with markets called souks selling spices, carpets, leather, lanterns and metalwork. Traditional houses called riads face inward around courtyard gardens, keeping them cool."],["Jemaa el-Fnaa","Jemaa el-Fnaa is the heart of Marrakesh. By day it hosts juice sellers and snake charmers; at night, rows of food stalls, musicians and storytellers fill it. UNESCO recognized the square as a masterpiece of intangible heritage in 2001, helping inspire the creation of its intangible heritage lists. In 2023, a strong earthquake damaged parts of the old city and nearby mountain villages."]],
k:[["Country","Morocco"],["Population","About 1 million"],["Founded","1070"],["Nickname","The Red City"],["Famous square","Jemaa el-Fnaa"]],
d:[["1070","Founded by the Almoravids"],["1150s","The Koutoubia Mosque is built"],["1500s","Capital of the Saadian dynasty"],["1985","The medina is listed by UNESCO"],["2001","Jemaa el-Fnaa recognized by UNESCO"],["2023","An earthquake damages the region"]],
s2:[["The Koutoubia Mosque","The Koutoubia Mosque’s minaret, about 77 meters tall, has been a landmark for travelers for over 800 years. By tradition, no building in the medina may be taller. Its design influenced the Giralda tower in Seville, Spain."],["The Majorelle Garden","The Majorelle Garden was created by French painter Jacques Majorelle from the 1920s, with exotic plants and buildings painted in an intense blue now called ‘Majorelle blue’. It was later bought and restored by fashion designer Yves Saint Laurent."]],
sp:["Storytellers of the square","For centuries, storytellers called hlaykia have gathered crowds in Jemaa el-Fnaa, telling tales from The Thousand and One Nights and local legends. Few remain today, and efforts are being made to keep this oral tradition alive."],
g:[["Medina","The old walled part of a North African city"],["Souk","A traditional market"],["Riad","A traditional house built around a courtyard garden"],["Minaret","A tall tower of a mosque"]],
f:["Marrakesh was founded in 1070.","The medina’s walls are about 19 kilometers long.","The Koutoubia minaret is about 77 meters tall."],
fun:"The name Morocco comes from the name Marrakesh.",
tl:"Ang Marrakesh ay makasaysayang lungsod sa Morocco na tinatawag na Pulang Lungsod dahil sa pulang pader nito. Tuwing gabi ay napupuno ng mga tagapagtanghal at kainan ang plaza nitong Jemaa el-Fnaa."});

ADDART({id:"victoriafalls",t:"Victoria Falls",c:"Geography",i:"💦",w:"Victoria Falls",r:["waterfalls","zimbabwecountry","rivers","rift","tourism"],
p:[["The smoke that thunders","Victoria Falls is a huge waterfall on the Zambezi River in southern Africa."],["A curtain of water","It is the largest curtain of falling water in the world."],["Spray seen from afar","Its spray can be seen from many kilometers away."]],
l:"Victoria Falls is a waterfall on the Zambezi River on the border between Zambia and Zimbabwe in southern Africa. About 1,708 meters wide and up to 108 meters high, it forms the largest single sheet of falling water in the world. The Kololo people called it Mosi-oa-Tunya, ‘the smoke that thunders’, for the roar of the water and the column of spray that can rise hundreds of meters and be seen from over 30 kilometers away. Scottish missionary and explorer David Livingstone named it after Queen Victoria in 1855. Victoria Falls is a UNESCO World Heritage Site and a center for tourism and adventure sports such as white-water rafting and bungee jumping.",
s:[["How the falls formed","The Zambezi flows across a flat plateau of basalt rock that cracked as it cooled long ago. The river has eaten into these cracks, carving a series of zigzag gorges below the falls. Over thousands of years, the falls have moved upstream as the river cuts back into new cracks, and they will keep moving."],["High and low water","The amount of water changes greatly with the seasons. In the rainy season, around April, over 500 million liters can plunge over the edge every minute, creating so much spray that the falls are hard to see. In the dry season, parts of the rock face are exposed."],["Wildlife and visitors","The falls are surrounded by national parks with elephants, hippos and many birds. The Victoria Falls Bridge, completed in 1905, crosses the gorge between Zambia and Zimbabwe. In the dry season, swimmers can sit in natural rock pools right at the edge of the falls."]],
k:[["River","Zambezi"],["Countries","Zambia and Zimbabwe"],["Width","About 1,708 m"],["Height","Up to 108 m"],["Local name","Mosi-oa-Tunya"]],
d:[["Thousands of years","The falls cut back through the rock"],["1855","Livingstone sees and names the falls"],["1905","The Victoria Falls Bridge is completed"],["1989","Listed as a UNESCO World Heritage Site"],["2019","Severe drought reduces the falls to a trickle in parts"]],
s2:[["Livingstone’s visit","In November 1855, David Livingstone was taken by canoe to a small island on the edge of the falls, now called Livingstone Island. He wrote that the scene was so lovely it must have been gazed upon by angels in their flight. He named the falls after Queen Victoria."],["Moonbows","On clear nights around the full moon, the spray of Victoria Falls can create a lunar rainbow, or ‘moonbow’, lit by moonlight. It is one of the few places in the world where moonbows are seen regularly."]],
sp:["The Devil’s Pool","During the dry season, when the river is low, visitors can swim with guides in a natural rock pool at the very lip of the falls on the Zambian side, called the Devil’s Pool, protected by a rock wall that stops them going over the edge."],
g:[["Gorge","A narrow valley with steep rocky sides"],["Plateau","A large, flat area of high land"],["Spray","Tiny drops of water flying through the air"],["Moonbow","A rainbow made by moonlight"]],
f:["Victoria Falls is about 1,708 meters wide.","Its spray can be seen from more than 30 kilometers away.","Moonbows can be seen there around the full moon."],
fun:"Victoria Falls is neither the tallest nor the widest waterfall, but it forms the largest single sheet of falling water.",
tl:"Ang Victoria Falls ay malaking talon sa Ilog Zambezi sa hangganan ng Zambia at Zimbabwe. Ito ang pinakamalaking kurtina ng bumabagsak na tubig sa mundo, at tinawag itong ‘usok na kumukulog’."});

ADDART({id:"serengeti",t:"The Serengeti",c:"Geography",i:"🦓",w:"Serengeti",r:["tanzaniacountry","kenyacountry","lion","grasslands","conservation"],
p:[["Endless plains","The Serengeti is a vast savanna in Tanzania and Kenya."],["The great migration","Over a million wildebeest travel in a yearly circle following the rains."],["Big cats","It has one of the largest populations of lions in Africa."]],
l:"The Serengeti is a vast ecosystem of grasslands, savanna and woodland in East Africa, stretching across northern Tanzania and into southwestern Kenya, where it is called the Maasai Mara. Its name comes from the Maasai word for ‘endless plains’. It is famous for the great migration, the yearly journey of over a million wildebeest, along with hundreds of thousands of zebras and gazelles, following the rains in search of fresh grass. Predators such as lions, leopards, cheetahs and hyenas follow the herds. Serengeti National Park, established in 1951, is a UNESCO World Heritage Site and one of the best-known wildlife areas in the world.",
s:[["The great migration","The wildebeest move in a giant loop of about 800 kilometers each year. In the wet season, they gather on the southern short-grass plains, where about half a million calves are born within a few weeks. As the plains dry, they head north and west, crossing crocodile-filled rivers such as the Mara, then return south when the rains come."],["Predators and prey","The Serengeti has around 3,000 lions, as well as leopards, cheetahs, hyenas and wild dogs. Vultures and other scavengers clean up after kills. Rocky outcrops called kopjes rise from the plains, providing lookouts and shelter for lions and other animals."],["Conservation","The Serengeti is protected by national parks and reserves, but faces threats from poaching, roads, growing human populations and climate change. The Maasai people traditionally herd cattle in the region, and how to balance conservation with local communities’ needs is an ongoing debate."]],
k:[["Countries","Tanzania and Kenya"],["Name means","‘Endless plains’ (Maasai)"],["Wildebeest","Over a million"],["National park founded","1951"],["UNESCO site","Since 1981"]],
d:[["Thousands of years","Migration patterns develop"],["1951","Serengeti National Park established"],["1959","‘Serengeti Shall Not Die’ book and film"],["1981","Listed as a UNESCO World Heritage Site"],["2010s","Plans for a highway across the park are dropped"]],
s2:[["River crossings","The most dramatic moments of the migration happen when herds must cross the Mara and Grumeti rivers. Thousands of wildebeest plunge into the water at once, braving strong currents and huge Nile crocodiles waiting below."],["Serengeti Shall Not Die","In the 1950s, German zoologist Bernhard Grzimek and his son Michael flew over the Serengeti to count animals and map their movements. Their book and Oscar-winning film ‘Serengeti Shall Not Die’ made the park famous worldwide. Michael died when their plane crashed in 1959."]],
sp:["Kopjes","Kopjes are granite outcrops that rise like islands from the grassy plains. They collect rainwater and support trees and plants, giving shelter to lions, leopards, rock hyraxes and snakes. Lions often rest on top to watch for prey."],
g:[["Savanna","Tropical grassland with scattered trees"],["Migration","A regular seasonal journey by animals"],["Kopje","A rocky hill rising from a plain"],["Predator","An animal that hunts other animals"]],
f:["Over a million wildebeest take part in the great migration.","About half a million wildebeest calves are born within a few weeks.","The Serengeti has around 3,000 lions."],
fun:"Wildebeest calves can stand and run within minutes of being born.",
tl:"Ang Serengeti ay malawak na savanna sa Tanzania at Kenya. Taun-taon, mahigit isang milyong wildebeest ang naglalakbay nang paikot sa paghahanap ng damo, at marami ritong leon."});

ADDART({id:"niagara",t:"Niagara Falls",c:"Geography",i:"🌊",w:"Niagara Falls",r:["waterfalls","canadacountry","usacountry","toronto","elec"],
p:[["Three waterfalls","Niagara Falls is a group of three waterfalls on the border of Canada and the United States."],["Huge power","More water flows over them than any other falls in North America."],["Electric pioneer","It was one of the first places to make hydroelectric power on a large scale."]],
l:"Niagara Falls is a group of three waterfalls on the Niagara River, which flows from Lake Erie to Lake Ontario along the border between Canada and the United States. The Horseshoe Falls, the largest, lies mostly in Canada, while the American Falls and the smaller Bridal Veil Falls are in the United States. About 2,400 cubic meters of water plunge over the falls every second during the summer tourist season, more than at any other waterfall in North America. The falls formed about 12,000 years ago at the end of the last Ice Age. Niagara has been a major tourist attraction since the 19th century and an early center of hydroelectric power.",
s:[["Formation","As the glaciers of the last Ice Age melted, water from the Great Lakes began flowing over a steep cliff called the Niagara Escarpment. The falls have since eroded about 11 kilometers upstream, leaving the Niagara Gorge. Erosion has been greatly slowed by diverting water for power and by engineering works."],["Power from the falls","In 1895, the Adams Power Plant at Niagara Falls began generating electricity using alternating current, the system championed by Nikola Tesla and George Westinghouse, and sent it to the city of Buffalo. It helped prove that electricity could be sent over long distances. Today, much of the river’s water is diverted through power stations, especially at night."],["Daredevils and tourists","Niagara has drawn honeymooners and tourists for over 150 years. Boats such as the Maid of the Mist carry visitors close to the base of the falls. Daredevils have crossed the gorge on tightropes and gone over the falls in barrels, often with tragic results; such stunts are now illegal."]],
k:[["River","Niagara"],["Countries","Canada and United States"],["Largest falls","Horseshoe Falls, mostly in Canada"],["Formed","About 12,000 years ago"],["Water flow","About 2,400 m³ per second (summer)"]],
d:[["c.12,000 years ago","The falls form after the Ice Age"],["1859","Charles Blondin crosses on a tightrope"],["1885","Niagara Reservation becomes New York’s first state park"],["1895","Large-scale hydroelectric power begins"],["1901","Annie Edson Taylor goes over in a barrel"],["1969","The American Falls are temporarily turned off for study"]],
s2:[["The first person over the falls","In 1901, on her 63rd birthday, schoolteacher Annie Edson Taylor became the first person to go over the Horseshoe Falls in a barrel and survive. She had hoped to become rich from the stunt but died poor."],["Turning off the falls","In 1969, US engineers built a temporary dam to stop the water flowing over the American Falls for several months so they could study rock falls and erosion. Visitors walked on the dry riverbed, where coins and other objects were found."]],
sp:["Lit up at night","Every night, the falls are lit with colored lights, and in summer there are regular fireworks displays. In very cold winters, ice builds up around the falls, creating spectacular frozen scenery, though the water never stops flowing completely."],
g:[["Escarpment","A long, steep slope or cliff"],["Hydroelectric power","Electricity made from flowing water"],["Gorge","A deep, narrow valley"],["Alternating current","Electric current that changes direction regularly"]],
f:["Niagara Falls is made up of three waterfalls.","The falls formed about 12,000 years ago.","The American Falls were turned off in 1969 for study."],
fun:"Niagara’s falls have moved about 11 kilometers upstream since they formed.",
tl:"Ang Niagara Falls ay tatlong talon sa hangganan ng Canada at Estados Unidos. Mas maraming tubig ang dumadaloy dito kaysa alinmang talon sa Hilagang Amerika, at isa ito sa mga unang pinagkunan ng kuryente mula sa tubig."});

ADDART({id:"yellowstone",t:"Yellowstone National Park",c:"Geography",i:"♨️",w:"Yellowstone National Park",r:["geysers","volc","usacountry","wolf","conservation"],
p:[["The first national park","Yellowstone, created in 1872, is often called the world’s first national park."],["Geysers and hot springs","It has about half of all the world’s active geysers."],["A supervolcano","It sits on top of a huge volcanic hotspot."]],
l:"Yellowstone National Park, mostly in the US state of Wyoming and extending into Montana and Idaho, was established in 1872 and is widely regarded as the first national park in the world. Covering about 8,991 square kilometers, it sits on a volcanic hotspot, where heat from deep inside the Earth powers over 10,000 hydrothermal features, including about half of the world’s active geysers, colorful hot springs, mud pots and steaming vents. Old Faithful, its most famous geyser, erupts many times a day. The park is also home to bison, grizzly bears, wolves, elk and many other animals. It is a UNESCO World Heritage Site and attracts millions of visitors each year.",
s:[["A supervolcano","Yellowstone lies on top of a huge chamber of hot and partly molten rock. Three enormous eruptions over the past 2.1 million years, the last about 640,000 years ago, created vast calderas. Scientists monitor the volcano closely. They consider another giant eruption very unlikely in the foreseeable future; small earthquakes and hydrothermal explosions are more common."],["Geysers and hot springs","Geysers form when water underground is heated under pressure until it bursts out as a fountain of water and steam. Old Faithful erupts roughly every 60 to 110 minutes. Grand Prismatic Spring, the largest hot spring in the United States, is ringed with bright bands of color made by heat-loving microbes."],["Wildlife","Yellowstone is one of the few places in the United States where bison have lived continuously since prehistoric times. Wolves were wiped out from the park by the 1920s and reintroduced in 1995, which changed the behavior of elk and helped plants and other animals recover."]],
k:[["Country","United States"],["States","Wyoming, Montana, Idaho"],["Established","1872"],["Area","About 8,991 km²"],["Famous geyser","Old Faithful"]],
d:[["c.640,000 years ago","The last supereruption"],["1870","An expedition explores the region"],["1872","Becomes the first national park"],["1978","Listed as a UNESCO World Heritage Site"],["1988","Large wildfires burn a third of the park"],["1995","Wolves are reintroduced"]],
s2:[["Bringing back the wolves","When gray wolves were reintroduced in 1995–1996, they began hunting elk, which had overgrazed river valleys. As elk moved more and grazed less in some places, willows and aspens grew back, providing food and homes for beavers and birds, an example of how one species can affect a whole ecosystem."],["Microbes in hot water","Yellowstone’s hot springs contain microbes that thrive in near-boiling water. In the 1960s, scientists found a bacterium there whose heat-resistant enzyme later made possible the PCR test, used to copy DNA in medicine, forensics and COVID-19 testing."]],
sp:["Old Faithful","Old Faithful earned its name in 1870 for its regular eruptions, which shoot boiling water up to about 55 meters into the air for a few minutes. Park rangers predict the next eruption based on the length of the previous one."],
g:[["Geyser","A hot spring that erupts with water and steam"],["Hotspot","A place where heat from deep in the Earth rises to the surface"],["Caldera","A large crater formed when a volcano collapses"],["Hydrothermal","Relating to hot water heated underground"]],
f:["Yellowstone has about half the world’s active geysers.","Wolves were reintroduced to the park in 1995.","A microbe from Yellowstone helped make the PCR test possible."],
fun:"Yellowstone has more than 10,000 hydrothermal features.",
tl:"Ang Yellowstone, itinatag noong 1872, ay itinuturing na unang pambansang liwasan sa mundo. Narito ang mga kalahati ng aktibong geyser sa mundo, at nakapatong ito sa isang malaking bulkan."});

ADDART({id:"eiffeltower",t:"The Eiffel Tower",c:"Countries and Places",i:"🗼",w:"Eiffel Tower",r:["francecountry","steel","architecture","tourism","frrev"],
p:[["Symbol of Paris","The Eiffel Tower is an iron tower in Paris, built for the 1889 World’s Fair."],["Once the tallest","It was the tallest structure in the world for 41 years."],["Nearly torn down","It was meant to stand for only 20 years."]],
l:"The Eiffel Tower is a wrought-iron lattice tower on the Champ de Mars in Paris, France. It was designed and built by the company of engineer Gustave Eiffel for the 1889 Exposition Universelle, a world’s fair marking the centenary of the French Revolution. At about 330 meters tall including antennas, it was the tallest human-made structure in the world until 1930. Many artists criticized it at first as ugly, and it was meant to be dismantled after 20 years, but it was saved because it proved useful for radio transmission. Today it is the most famous symbol of Paris and France, visited by around 6 million people a year.",
s:[["Building the tower","The tower was built in just over two years, from 1887 to 1889, by around 300 workers. It is made of about 18,000 iron parts joined by 2.5 million rivets, assembled like a giant construction kit. Its curved shape was designed to resist the wind. Remarkably, only one worker is recorded as having died during construction."],["Saved by radio","In 1887, a group of famous artists and writers published a protest against the ‘useless and monstrous’ tower. Eiffel’s permit was for 20 years, but he promoted scientific uses, including weather observations and radio. In the early 20th century, it became an important radio transmitter, and the military value of radio saved it from demolition."],["A global icon","The tower has three levels open to visitors, reached by stairs and elevators. It is repainted by hand about every seven years, using around 60 tonnes of paint. At night, it sparkles with 20,000 light bulbs for five minutes every hour."]],
k:[["City","Paris, France"],["Completed","1889"],["Height","About 330 m with antennas"],["Material","Wrought iron, about 7,300 t"],["Visitors","About 6 million a year"]],
d:[["1887","Construction begins"],["1889","Opens for the World’s Fair"],["1909","Saved from demolition"],["1930","Overtaken by the Chrysler Building as tallest"],["1985","New lighting is installed"],["2024","Olympic rings displayed for the Paris Games"]],
s2:[["Eiffel’s office","At the very top of the tower, Gustave Eiffel built a small private apartment, where he received guests such as the inventor Thomas Edison in 1889. Today it can be seen by visitors, with wax figures of Eiffel and Edison."],["Growing in summer","Iron expands when it gets warm. On hot summer days, the tower can grow by up to about 15 centimeters, and its top can lean slightly away from the sun."]],
sp:["The sparkle","Since 2000, the tower has sparkled for five minutes at the start of every hour after dark, lit by 20,000 flashing bulbs installed by a team of climbers. At the top, two powerful searchlights sweep across the Paris sky."],
g:[["Lattice","A framework of crossed strips"],["Wrought iron","Iron that is tough and can be hammered into shape"],["Rivet","A metal pin used to join pieces of metal"],["World’s fair","A large international exhibition"]],
f:["The Eiffel Tower was built for the 1889 World’s Fair.","It is held together by about 2.5 million rivets.","It is repainted about every seven years."],
fun:"The Eiffel Tower can be about 15 centimeters taller in summer because iron expands in the heat.",
tl:"Ang Eiffel Tower ay toreng bakal sa Paris na itinayo para sa World’s Fair noong 1889. Ito ang pinakamataas na istruktura sa mundo nang 41 taon at dapat sana ay nakatayo lamang nang 20 taon."});

ADDART({id:"statueofliberty",t:"The Statue of Liberty",c:"Countries and Places",i:"🗽",w:"Statue of Liberty",r:["usacountry","francecountry","migration","usrev","newyork"],
p:[["A gift from France","The Statue of Liberty was given by the people of France to the United States."],["A symbol of freedom","Her torch and crown have welcomed ships to New York since 1886."],["Made of copper","Her green color comes from weathered copper."]],
l:"The Statue of Liberty, officially ‘Liberty Enlightening the World’, is a colossal copper statue on Liberty Island in New York Harbor. Designed by French sculptor Frédéric Auguste Bartholdi, with an internal iron framework engineered by Gustave Eiffel, it was a gift from the people of France to the United States, celebrating friendship and the ideals of liberty, and was dedicated in 1886. The robed figure represents Libertas, the Roman goddess of liberty, holding a torch aloft and a tablet inscribed with the date of the American Declaration of Independence. For millions of immigrants arriving by sea, she was the first sight of America. The statue is a UNESCO World Heritage Site.",
s:[["Building the statue","The idea came from French political thinker Édouard de Laboulaye, an admirer of American democracy and the abolition of slavery. Bartholdi built the statue in France from thin copper sheets hammered into shape and attached to Eiffel’s iron skeleton. It was shipped to New York in 350 pieces in 1885. Americans raised money for the pedestal, helped by a newspaper campaign by Joseph Pulitzer."],["Symbols","Liberty holds a torch, symbolizing enlightenment, and a tablet inscribed ‘July IV MDCCLXXVI’, the date of the Declaration of Independence. A broken chain and shackle lie at her feet, a symbol of freedom from oppression. Her crown has seven rays, often said to represent the seven continents and seas."],["Welcoming immigrants","Between 1892 and 1954, about 12 million immigrants passed through nearby Ellis Island. A plaque inside the pedestal carries Emma Lazarus’s poem ‘The New Colossus’, with the famous lines ‘Give me your tired, your poor, your huddled masses yearning to breathe free’."]],
k:[["Location","Liberty Island, New York Harbor"],["Dedicated","28 October 1886"],["Height","About 93 m including pedestal"],["Designer","Frédéric Auguste Bartholdi"],["Material","Copper over an iron frame"]],
d:[["1865","The idea is proposed in France"],["1876","The torch arm is displayed in Philadelphia"],["1884","The statue is completed in Paris"],["1886","Dedicated in New York"],["1892","Ellis Island immigration station opens"],["1984","Listed as a UNESCO World Heritage Site"]],
s2:[["Turning green","When the statue was dedicated, it was the reddish-brown color of new copper. Over about 30 years, exposure to air and seawater formed a green layer called patina, which actually protects the copper underneath from further corrosion."],["The torch","The statue’s original torch was replaced in 1986 by a new one covered in gold leaf. The original is now displayed in the Statue of Liberty Museum on the island. Visitors have not been allowed up into the torch since 1916."]],
sp:["The New Colossus","Emma Lazarus wrote her poem ‘The New Colossus’ in 1883 to help raise money for the pedestal. It imagined the statue as the ‘Mother of Exiles’ welcoming refugees. In 1903, the poem was engraved on a plaque placed inside the pedestal."],
g:[["Pedestal","The base on which a statue stands"],["Patina","A green layer that forms on copper over time"],["Colossal","Extremely large"],["Immigrant","A person who moves to live in another country"]],
f:["The Statue of Liberty was a gift from France.","It was shipped to New York in 350 pieces.","Its green color comes from weathered copper."],
fun:"The statue’s skin is copper only about 2.4 millimeters thick, about the thickness of two coins.",
tl:"Ang Statue of Liberty ay regalo ng mga mamamayan ng France sa Estados Unidos. Simbolo ito ng kalayaan na sumasalubong sa mga barko sa New York mula 1886, at berde ito dahil sa lumang tanso."});

ADDART({id:"alhambra",t:"The Alhambra",c:"Countries and Places",i:"🕌",w:"Alhambra",r:["spaincountry","islamicart","architecture","caliphate","castles"],
p:[["A palace-fortress","The Alhambra is a palace and fortress complex in Granada, Spain."],["Islamic art","It is one of the finest examples of Islamic architecture in Europe."],["Courtyards and fountains","Its gardens, pools and carved walls are famous for their beauty."]],
l:"The Alhambra is a palace and fortress complex on a hill overlooking the city of Granada in southern Spain. Most of it was built in the 13th and 14th centuries by the Nasrid dynasty, the last Muslim rulers in the Iberian Peninsula. Its name comes from the Arabic for ‘the red one’, after the reddish color of its walls. Inside, a series of palaces surround courtyards with pools and fountains, decorated with intricate carved plaster, colorful tiles, wooden ceilings and Arabic inscriptions. After Granada fell to the Catholic Monarchs Ferdinand and Isabella in 1492, Christian rulers added their own buildings. The Alhambra and the nearby Generalife gardens are a UNESCO World Heritage Site and one of Spain’s most visited monuments.",
s:[["The Nasrid palaces","The Nasrid kingdom of Granada lasted from 1238 to 1492, the last Muslim state in Spain. Its rulers built a fortress, the Alcazaba, and splendid palaces. The Court of the Lions has a fountain supported by twelve marble lions, and the Hall of the Abencerrajes has a dazzling ceiling of honeycomb-like carvings called muqarnas."],["Decoration","Because Islamic religious art avoids images of people, the Alhambra’s walls are covered with geometric patterns, plant designs and Arabic calligraphy, including poems and the repeated motto ‘There is no victor but God’. Its tiled patterns have fascinated mathematicians and inspired the Dutch artist M. C. Escher."],["After 1492","In January 1492, the last Nasrid sultan, Muhammad XII, known as Boabdil, surrendered Granada to Ferdinand and Isabella. That same year, Columbus received royal support for his voyage at Granada. Emperor Charles V later built a Renaissance palace within the Alhambra. The complex was neglected for centuries before being restored in the 19th and 20th centuries."]],
k:[["Location","Granada, Spain"],["Built by","The Nasrid dynasty"],["Main period","13th–14th centuries"],["Name means","‘The red one’ (Arabic)"],["UNESCO site","Since 1984"]],
d:[["1238","The Nasrid kingdom of Granada is founded"],["1300s","The main palaces are built"],["1492","Granada surrenders to Ferdinand and Isabella"],["1527","Charles V begins his palace"],["1829","Washington Irving writes about the Alhambra"],["1984","Listed as a UNESCO World Heritage Site"]],
s2:[["The Court of the Lions","The Court of the Lions, built in the late 14th century, is surrounded by slender columns and arches. At its center, water flows from the mouths of twelve marble lions into channels that run in four directions, possibly representing the four rivers of paradise."],["Tales of the Alhambra","In 1829, American writer Washington Irving lived in the Alhambra’s rooms for a time and wrote ‘Tales of the Alhambra’, a mix of history and legend that made the palace famous among travelers and encouraged its restoration."]],
sp:["The Generalife","Beside the Alhambra lies the Generalife, a summer palace with terraced gardens, fountains and long pools lined with flowers. Its Court of the Water Channel is one of the oldest surviving Moorish gardens."],
g:[["Nasrid","The last Muslim dynasty to rule in Spain"],["Muqarnas","Honeycomb-like decoration on ceilings and arches"],["Calligraphy","Beautiful, decorative handwriting"],["Alcazaba","A Moorish fortress"]],
f:["The Alhambra’s name means ‘the red one’ in Arabic.","The Court of the Lions has twelve marble lions.","Granada fell to Ferdinand and Isabella in 1492."],
fun:"The tile patterns of the Alhambra inspired the artist M. C. Escher’s famous repeating designs.",
tl:"Ang Alhambra ay palasyo at kuta sa Granada, Espanya, na isa sa pinakamagagandang halimbawa ng arkitekturang Islamiko sa Europa. Tanyag ito sa mga patyo, fountain at inukit na pader."});
